# Prepare health report payload
payload=$(cat <<EOF
{
  "port_status": {
    "3000": $(if nc -z -w2 127.0.0.1 3000 >/dev/null 2>&1; then echo "true"; else echo "false"; fi),
    "8080": $(if nc -z -w2 127.0.0.1 8080 >/dev/null 2>&1; then echo "true"; else echo "false"; fi)
  },
  "env": {
$(awk -F= 'BEGIN{first=1} /^[A-Za-z_][A-Za-z0-9_]*=/ {gsub(/"/,"\\\""); if (!first) printf ",\n"; printf "    \"%s\": \"%s\"", $1, $2; first=0}' .env.test)
  }
}
EOF
)

# Send health report
curl -s -X POST -H "Content-Type: application/json" -d "$payload" http://localhost:47301/api/health-report || echo "[WARN] Failed to send health report"

exit $overall_status

